#!/usr/bin/env python3
"""Pinned, self-contained launcher for the MIME-patched desktop successor.

The bundle is populated by the release build. Every member is verified before
any member executes. The retained original package remains untouched; a private
copy supplies its frozen dependencies together with the two new public trees.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import socket
import stat
import subprocess
import sys
import tempfile
import types

ROOT_REV = '1e651117deabb4c6935933ee424237d82bd316cb'
ROOT_SHA = '90d9dff5ff0fcadb4854f5f0dc2103dcfe8b9b25ef9922164fba1b6e690a03e9'
CORE = '22f724b1ec75e8326e20305df40b91fe5640a7a7'
SEED = '6a9afe74203995a36416373528de5a29097fee83'
REMOTE = 'https://github.com/omarmakramelbaz-hub/F-Backend.git'
DEPENDENCY_REVISIONS = ('43b1498938d4550a4c63c267dbcde12b0bab7e81', '11c739039e5c6320b3542d414682d755c7902790', '052e69008da7e330815b376824cd8afc18cf04c1', 'dc06af6f8e4ef9ea03a3fb9c728d26acb2f8193a', 'd1976ce02c553939032241e7e724d26a9bbe7190', '3e997647e9e767a774e7c62e68f562e1f1a36416', '18e13894c1afcc9f3daa61df2446b02cf806cb7a', '2d9e23a5157782882382c797a44ad15c317ae845', '12d74b4f35737a2b1e271657b159137538c3edaf', '33e08c9fec93501d2376eb88d9fd402043f8d792', '8db5adb538834a2152f74f6e55336223a4c95908', '5628a33525e2af63b221f044eb0e650cb6a2b790', '13fd8b038bd1a853a30ba9b4140a053088efa73d', '0885a3b550f92df2b74bcd2c16d27954d8b44b7b', '9867dc29357e16290b3a1eeda996d916af701915', 'f3a8b4af4ec27042a93328c1fde200cfd8fe1da3', 'be797004831cbd8ccfb7c011aac855d6c2964829', '5becb9bab38a91998d1b1341670b2b398e4ba70f', 'b5503e21e3af32eecaf0d2f9d68eee7d21be7439', 'd15942c947ac31c21a90b53856084a5de35d3cc3', '766f9d2d101fd639ffea8905e5b309f03eab8759', '6e39001095dbf5909c7b58cff69914c50da0f200')
BUNDLED_MODULES = {'payloads': ('c2352af7799d96104a48192b0fe221b770189041f258e495c85e3661e768d459', ''), 'current': ('ed150df9b047357aa88548a02f2701cdb0f9fe240f0212349a17dfc62189a09c', ''), 'source': ('f5c7e184641b98b49683938a8131c73662eb53d60b86ea0498a8e2f1afddb023', ''), 'coordinator': ('64f9b28ead0916c69314557fb9f38bd0c2d0d6f1f3f98637941289f1f660e9a3', ''), 'recovery_plan': ('9dfa770a163bf6866cd19007743050094cd0a7be57ddb5afaf0fe54e4d3284b2', ''), 'recovery_evidence': ('76062c79ced7f139364c3a0804dd35cbf26d703e1b8483077e291273134bb690', ''), 'recovery_effects': ('c77490cb02ae7dd3e287f0e16019301461ddd5f0687d8e637cbdb23d70b593a5', ''), 'successor_plan': ('0b52535ebe53cc5ee063dc00a660bdb69f0940ff44ddb4d56b8a10b4c7bfdea0', ''), 'successor_coordinator': ('5db8c12f119cc0822838c44ec0cd062f57e3f00a5be9d3ee15ae33b4d57205d8', '')}
ROLES = ('payloads', 'current', 'source', 'coordinator', 'recovery_plan', 'recovery_evidence', 'recovery_effects', 'successor_plan', 'successor_coordinator')
ENVIRONMENT = {'PATH': '/usr/bin:/bin', 'GIT_CONFIG_NOSYSTEM': '1',
    'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_CONFIG_SYSTEM': '/dev/null',
    'GIT_NO_REPLACE_OBJECTS': '1', 'GIT_NO_LAZY_FETCH': '1',
    'GIT_OPTIONAL_LOCKS': '0', 'GIT_TERMINAL_PROMPT': '0', 'LC_ALL': 'C'}


class Stop(Exception):
    pass


def need(value, code):
    if not value:
        raise Stop('GO_ERP_DESKTOP_PERFORMANCE_LAUNCHER_' + code)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def load(raw, role, expected):
    need(isinstance(raw, bytes) and sha(raw) == expected, 'MODULE_HASH_CHANGED')
    result = types.ModuleType('performance_upgrade_' + role)
    result.__file__ = '<pinned-performance-' + role + '>'
    sys.modules[result.__name__] = result
    exec(compile(raw, result.__file__, 'exec'), result.__dict__)
    return result


def helpers():
    need(isinstance(BUNDLED_MODULES, dict) and set(BUNDLED_MODULES) == set(ROLES), 'BUNDLE_MISSING')
    checked = {}
    for role in ROLES:
        row = BUNDLED_MODULES[role]
        need(isinstance(row, (tuple, list)) and len(row) == 2, 'BUNDLE_INVALID')
        expected, encoded = row
        need(isinstance(expected, str) and re.fullmatch(r'[a-f0-9]{64}', expected)
             and isinstance(encoded, str) and len(encoded) <= 512 * 1024, 'BUNDLE_INVALID')
        try:
            raw = base64.b64decode(encoded, validate=True)
        except (TypeError, ValueError):
            raise Stop('GO_ERP_DESKTOP_PERFORMANCE_LAUNCHER_BUNDLE_INVALID') from None
        need(sha(raw) == expected, 'MODULE_HASH_CHANGED')
        checked[role] = (raw, expected)
    return {role: load(raw, role, expected) for role, (raw, expected) in checked.items()}


def safe_directory(path):
    info = path.lstat()
    return (stat.S_ISDIR(info.st_mode) and info.st_uid == 0
            and not info.st_mode & 0o022 and path.resolve() == path)


def git(repository, *arguments):
    result = subprocess.run(['/usr/bin/git', '--git-dir=' + str(repository),
        '-c', 'credential.helper=', '-c', 'core.hooksPath=/dev/null',
        '-c', 'core.attributesFile=/dev/null', '-c', 'core.fsmonitor=false',
        '-c', 'submodule.recurse=false', *arguments], stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=240,
        env=ENVIRONMENT)
    need(result.returncode == 0 and len(result.stdout) <= 16 * 1024 ** 2, 'GIT_FAILED')
    return result.stdout


def retained_package():
    rows = []
    for folder in Path('/var/tmp').glob('go-erp-shared-workspace.*'):
        try:
            rows.append((folder.lstat().st_mtime_ns, folder))
        except OSError:
            continue
    for _modified, folder in sorted(rows, key=lambda row: row[0], reverse=True)[:64]:
        repository = folder / 'release.git'
        try:
            if not (safe_directory(folder) and safe_directory(repository)):
                continue
            raw = git(repository, 'show', ROOT_REV + ':deployment/go_erp_shared_workspace_root.py')
            if sha(raw) == ROOT_SHA:
                return repository, raw
        except (OSError, subprocess.SubprocessError, Stop):
            continue
    raise Stop('GO_ERP_DESKTOP_PERFORMANCE_LAUNCHER_PINNED_PACKAGE_NOT_FOUND')


def prepare_package(original_repository, stage):
    need(safe_directory(original_repository.parent) and safe_directory(original_repository)
         and safe_directory(stage), 'PACKAGE_DIRECTORY_UNSAFE')
    repository = stage / 'release.git'
    # Bare local cloning executes no checkout or application code. Avoid hard
    # links so object additions never modify the retained source package.
    result = subprocess.run(['/usr/bin/git', '-c', 'credential.helper=',
        '-c', 'core.hooksPath=/dev/null', '-c', 'core.fsmonitor=false',
        'clone', '--quiet', '--bare', '--local', '--no-hardlinks', '--',
        str(original_repository), str(repository)], stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=240,
        env=ENVIRONMENT)
    need(result.returncode == 0 and safe_directory(repository), 'PACKAGE_COPY_FAILED')
    need(not os.path.lexists(repository / 'objects/info/alternates'), 'PACKAGE_ALTERNATES_NOT_ALLOWED')
    # Git ignores --local for a shallow source. A retained package fetched by
    # raw SHA can also have no branch refs, so cloning it can produce an empty
    # object store. Explicitly fetch the complete immutable package roster;
    # neither the clone nor commit ancestry is an authority for dependencies.
    revisions = tuple(dict.fromkeys((ROOT_REV, CORE, SEED, *DEPENDENCY_REVISIONS)))
    git(repository, 'fetch', '--quiet', '--depth=1', '--no-tags',
        '--no-recurse-submodules', REMOTE, *revisions)
    for revision in revisions:
        need(git(repository, 'rev-parse', revision + '^{commit}').strip() == revision.encode(),
             'PACKAGE_REVISION_CHANGED')
    need(sha(git(repository, 'show', ROOT_REV + ':deployment/go_erp_shared_workspace_root.py')) == ROOT_SHA,
         'ORIGINAL_ROOT_CHANGED')
    return repository


def failure(error, phase):
    message = str(error)
    if re.fullmatch(r'GO_ERP_[A-Z0-9_]{1,170}', message):
        code = message
    elif re.fullmatch(r'NATIVE_TRANSACTION_[A-Z0-9_]{1,70}', message):
        # Frozen native prepare returns only its bounded public reason code.
        # Preserve it without exposing exception text from other failures.
        code = 'GO_ERP_DESKTOP_PERFORMANCE_' + message
    else:
        code = 'GO_ERP_DESKTOP_PERFORMANCE_UPGRADE_FAILURE'
    frames, tb = [], error.__traceback__
    while tb:
        frames.append([Path(tb.tb_frame.f_code.co_filename).name, tb.tb_frame.f_code.co_name, tb.tb_lineno])
        tb = tb.tb_next
    return {'code': code, 'phase': phase, 'error_type': type(error).__name__, 'frames': frames[-8:]}


def public_result(value):
    expected = {'format': 1, 'kind': 'go-erp-desktop-performance-rollout',
        'ok': True, 'published': True, 'version': '0.4.4-preview.62',
        'workspace_enabled': True, 'manual_only': True,
        'automatic_updates_enabled': False, 'database_changed': False,
        'financial_data_changed': False, 'credentials_disclosed': False}
    need(isinstance(value, dict) and set(value) == set(expected) | {'candidate_revision'},
         'RESULT_FIELDS_CHANGED')
    need(all(type(value[name]) is type(item) and value[name] == item
             for name, item in expected.items()), 'RESULT_SCOPE_CHANGED')
    need(isinstance(value['candidate_revision'], str)
         and re.fullmatch(r'[a-f0-9]{40}', value['candidate_revision']), 'RESULT_CANDIDATE_INVALID')
    return value


def main():
    stage, phase, complete = None, 'host', False
    try:
        need(os.geteuid() == 0 and socket.gethostname().split('.')[0] == 'srv1836524', 'ROOT_HOST_REQUIRED')
        need(len(sys.argv) == 1, 'ARGUMENTS_NOT_ALLOWED')
        phase = 'helpers'
        modules = helpers()
        phase = 'retained-package'
        original_repository, original_raw = retained_package()
        phase = 'package'
        print('GO_ERP_DESKTOP_PERFORMANCE_PACKAGE_PREPARING', flush=True)
        stage = Path(tempfile.mkdtemp(prefix='go-erp-desktop-performance.', dir='/var/tmp'))
        repository = prepare_package(original_repository, stage)
        original = load(original_raw, 'original_root', ROOT_SHA)
        package = original.Package(repository, ROOT_REV)
        operator = original.Operator(package, original.PINS)
        phase = 'upgrade'
        result = modules['successor_coordinator'].run(package, operator, modules)
        phase = 'result'
        print(json.dumps(public_result(result), sort_keys=True, separators=(',', ':'), allow_nan=False))
        complete = True
        return 0
    except BaseException as error:
        print(json.dumps(failure(error, phase), sort_keys=True, separators=(',', ':')))
        return 1
    finally:
        if stage is not None:
            if complete:
                shutil.rmtree(stage)
            else:
                print('GO_ERP_DESKTOP_PERFORMANCE_PACKAGE_RETAINED_RETRY_SAME_COMMAND')


if __name__ == '__main__':
    raise SystemExit(main())
